// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.rule.builtinimport com.roshan.persona.brain.intent.Intentimport com.roshan.persona.brain.rule.BrainRuleimport com.roshan.persona.brain.rule.RuleActionimport com.roshan.persona.brain.rule.RuleConditionimport com.roshan.persona.brain.skill.AudioStreamimport com.roshan.persona.brain.skill.DndModeimport com.roshan.persona.brain.skill.RingerModeimport com.roshan.persona.brain.skill.SystemOperationimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Built-in system rules. * * These rules handle instant system control intents (torch, volume, brightness, * mute, ringer). They never touch the LLM. * * Priority order: 10 (highest — these should fire before any other rule). * * Note: For rules where the action depends on intent slots (e.g., VolumeUp * with amount), we use a default action here. The RuleExecutor (Step 2.8) * will override with actual slot values at execution time. */// ─── Torch rules ───────────────────────────────────────────────────────────@Singletonclass TorchOnRule @Inject constructor() : BrainRule {    override val id = "torch_on_rule"    override val priority = 10    override val tags = setOf("system", "torch")    override val description = "Turn on the torch instantly"    override val condition = RuleCondition.IntentIs(Intent.TorchOn::class)    override val action = RuleAction.SystemCall(SystemOperation.SetTorch(on = true))}@Singletonclass TorchOffRule @Inject constructor() : BrainRule {    override val id = "torch_off_rule"    override val priority = 10    override val tags = setOf("system", "torch")    override val description = "Turn off the torch instantly"    override val condition = RuleCondition.IntentIs(Intent.TorchOff::class)    override val action = RuleAction.SystemCall(SystemOperation.SetTorch(on = false))}// ─── Volume rules ──────────────────────────────────────────────────────────@Singletonclass VolumeUpRule @Inject constructor() : BrainRule {    override val id = "volume_up_rule"    override val priority = 10    override val tags = setOf("system", "volume")    override val description = "Increase volume by 1 step (or custom amount)"    override val condition = RuleCondition.IntentIs(Intent.VolumeUp::class)    override val action = RuleAction.SystemCall(        SystemOperation.AdjustVolume(delta = 1, stream = AudioStream.MEDIA)    )}@Singletonclass VolumeDownRule @Inject constructor() : BrainRule {    override val id = "volume_down_rule"    override val priority = 10    override val tags = setOf("system", "volume")    override val description = "Decrease volume by 1 step (or custom amount)"    override val condition = RuleCondition.IntentIs(Intent.VolumeDown::class)    override val action = RuleAction.SystemCall(        SystemOperation.AdjustVolume(delta = -1, stream = AudioStream.MEDIA)    )}@Singletonclass SetVolumeRule @Inject constructor() : BrainRule {    override val id = "set_volume_rule"    override val priority = 10    override val tags = setOf("system", "volume")    override val description = "Set volume to specific level"    override val condition = RuleCondition.IntentIs(Intent.SetVolume::class)    override val action = RuleAction.SystemCall(        SystemOperation.SetVolume(level = 50, stream = AudioStream.MEDIA)    )}// ─── Brightness rules ──────────────────────────────────────────────────────@Singletonclass SetBrightnessRule @Inject constructor() : BrainRule {    override val id = "set_brightness_rule"    override val priority = 10    override val tags = setOf("system", "brightness")    override val description = "Set display brightness"    override val condition = RuleCondition.IntentIs(Intent.SetBrightness::class)    override val action = RuleAction.SystemCall(        SystemOperation.SetDisplayBrightness(level = 0.5f)    )}/** Strategy §2: BrightnessUp rule — increments brightness by ~10%. */@Singletonclass BrightnessUpRule @Inject constructor() : BrainRule {    override val id = "brightness_up_rule"    override val priority = 10    override val tags = setOf("system", "brightness")    override val description = "Increase brightness by 10%"    override val condition = RuleCondition.IntentIs(Intent.BrightnessUp::class)    override val action = RuleAction.SystemCall(        SystemOperation.AdjustDisplayBrightness(delta = +0.1f)    )}/** Strategy §2: BrightnessDown rule — decrements brightness by ~10%. */@Singletonclass BrightnessDownRule @Inject constructor() : BrainRule {    override val id = "brightness_down_rule"    override val priority = 10    override val tags = setOf("system", "brightness")    override val description = "Decrease brightness by 10%"    override val condition = RuleCondition.IntentIs(Intent.BrightnessDown::class)    override val action = RuleAction.SystemCall(        SystemOperation.AdjustDisplayBrightness(delta = -0.1f)    )}// ─── Screen on/off rules (strategy §2: 9 built-in rules) ──────────────────@Singletonclass ScreenOnRule @Inject constructor() : BrainRule {    override val id = "screen_on_rule"    override val priority = 10    override val tags = setOf("system", "screen")    override val description = "Wake the screen"    override val condition = RuleCondition.IntentIs(Intent.ScreenOn::class)    override val action = RuleAction.SystemCall(SystemOperation.ScreenOn)}@Singletonclass ScreenOffRule @Inject constructor() : BrainRule {    override val id = "screen_off_rule"    override val priority = 10    override val tags = setOf("system", "screen")    override val description = "Lock the screen"    override val condition = RuleCondition.IntentIs(Intent.ScreenOff::class)    override val action = RuleAction.SystemCall(SystemOperation.ScreenOff)}// ─── DND rule ──────────────────────────────────────────────────────────────@Singletonclass ToggleDndRule @Inject constructor() : BrainRule {    override val id = "toggle_dnd_rule"    override val priority = 10    override val tags = setOf("system", "dnd")    override val description = "Toggle Do Not Disturb (priority only)"    override val condition = RuleCondition.IntentIs(Intent.ToggleDnd::class)    override val action = RuleAction.SystemCall(        SystemOperation.SetDndMode(mode = DndMode.PRIORITY)    )}// ─── Battery saver rule ────────────────────────────────────────────────────@Singletonclass ToggleBatterySaverRule @Inject constructor() : BrainRule {    override val id = "toggle_battery_saver_rule"    override val priority = 10    override val tags = setOf("system", "battery")    override val description = "Toggle Battery Saver mode"    override val condition = RuleCondition.IntentIs(Intent.ToggleBatterySaver::class)    override val action = RuleAction.SystemCall(        SystemOperation.SetBatterySaver(enabled = true)    )}// ─── Mute / Unmute rules ───────────────────────────────────────────────────@Singletonclass MuteRule @Inject constructor() : BrainRule {    override val id = "mute_rule"    override val priority = 10    override val tags = setOf("system", "mute")    override val description = "Mute all audio (set ringer to silent)"    override val condition = RuleCondition.IntentIs(Intent.Mute::class)    override val action = RuleAction.SystemCall(        SystemOperation.SetRingerMode(mode = RingerMode.SILENT)    )}@Singletonclass UnmuteRule @Inject constructor() : BrainRule {    override val id = "unmute_rule"    override val priority = 10    override val tags = setOf("system", "mute")    override val description = "Unmute audio (set ringer to normal)"    override val condition = RuleCondition.IntentIs(Intent.Unmute::class)    override val action = RuleAction.SystemCall(        SystemOperation.SetRingerMode(mode = RingerMode.NORMAL)    )}// ─── List automations rule ─────────────────────────────────────────────────@Singletonclass ListAutomationsRule @Inject constructor() : BrainRule {    override val id = "list_automations_rule"    override val priority = 20    override val tags = setOf("automation")    override val description = "List all user automations"    override val condition = RuleCondition.IntentIs(Intent.ListAutomations::class)    override val action = RuleAction.SkillInvoke(        skillId = "automation_list",        params = emptyMap(),    )}